/* Implementation B: an INDEPENDENT twin of the Delta=4 pruned traversal.
 *
 * Deliberately written the slow, literal way: at every node it recomputes deg, e22,
 * rem22, touched and fixedSlack FROM SCRATCH by scanning, exactly as the Lean
 * definitions do, with no suffix tables and no accumulators.  model_a.py keeps all
 * of those as accumulators/suffix tables.  Agreement between the two is therefore a
 * real check rather than a check of one implementation against itself.
 *
 * Masks are generated by an independent genMask; pairList is rebuilt independently.
 *
 * usage:  ./model_b census
 *         ./model_b layer <n>
 *         ./model_b expand <n> <K> <d>
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef unsigned long long u64;

static int N;              /* shell size            */
static u64 KK;             /* mask word             */
static int MK[12], KW[12]; /* per-slot mask, weight */
static int N3, N4;
static int PI[66], PJ[66], NP; /* pairList            */
static unsigned ROW[12];       /* adjacency rows      */

static int popc(unsigned x){ int c=0; while(x){c+=x&1;x>>=1;} return c; }

/* ---- Model.msk / kwt ---- */
static void setctx(int n, u64 K){
  N=n; KK=K; N3=N4=0;
  for(int i=0;i<n;i++){
    u64 p=1; for(int t=0;t<i;t++) p*=16;
    MK[i]=(int)((K/p)%16);
    KW[i]=popc((unsigned)MK[i]);
    if(KW[i]==3) N3++;
    if(KW[i]==4) N4++;
  }
  NP=0;
  for(int i=n-1;i>=0;i--) for(int j=i-1;j>=0;j--){ PI[NP]=i; PJ[NP]=j; NP++; }
}

/* ---- Model.deg, recomputed ---- */
static int degf(int i){ int d=0; for(int j=0;j<N;j++) if((ROW[i]>>j)&1) d++; return d; }

/* ---- Model.e22, recomputed ---- */
static int e22f(void){
  int e=0;
  for(int i=0;i<N;i++) for(int j=0;j<i;j++)
    if(KW[i]==2 && KW[j]==2 && ((ROW[i]>>j)&1)) e++;
  return e;
}

/* ---- Prune.rem22 over the suffix ps[t:], recomputed ---- */
static int rem22f(int t){
  int r=0;
  for(int u=t;u<NP;u++){
    int i=PI[u], j=PJ[u];
    if(KW[i]==2 && KW[j]==2 && (MK[i]&MK[j])==0) r++;
  }
  return r;
}

/* ---- Prune.touched, recomputed ---- */
static int touchedf(int t,int x){
  for(int u=t;u<NP;u++) if(PI[u]==x||PJ[u]==x) return 1;
  return 0;
}

/* ---- Prune.fixedSlack, recomputed ---- */
static int fixedSlackf(int t){
  int s=0;
  for(int x=0;x<N;x++){
    if(touchedf(t,x)) continue;
    int sl = 4-KW[x]-degf(x); if(sl<0) sl=0;
    int w  = 2*KW[x]-1; if(w<0) w=0;
    s += w*sl;
  }
  return s;
}

/* ---- Prune.pruneOK ---- */
static int pruneOKf(int t){
  return 36 + 2*(e22f()+rem22f(t)) < 38 + 4*N3 + 12*N4 + fixedSlackf(t);
}

/* ---- Search.takeGuard ---- */
static int takeGuardf(int i,int j){
  if(KW[i]+degf(i) >= 4) return 0;
  if(KW[j]+degf(j) >= 4) return 0;
  if((MK[i]&MK[j])!=0) return 0;
  for(int t=0;t<N;t++) if(((ROW[i]>>t)&1) && ((ROW[j]>>t)&1)) return 0;
  return 1;
}

/* ---- Model.leafOK ---- */
static int certf(int k){ return k==1?1:(k==2?3:0); }

static int leafOKf(void){
  int hasL[12][4];
  for(int i=0;i<N;i++) for(int a=0;a<4;a++) hasL[i][a]=(MK[i]>>a)&1;
  int twoT=0;
  for(int i=0;i<N;i++) for(int j=0;j<N;j++)
    if((ROW[i]>>j)&1) twoT += KW[i]*KW[j];
  if(twoT<38) return 1;
  int rootW[4][4];
  for(int a=0;a<4;a++) for(int b=0;b<4;b++){
    int s=0; for(int i=0;i<N;i++) s+=hasL[i][a]*hasL[i][b]; rootW[a][b]=s;
  }
  int shellW[4][12];
  for(int a=0;a<4;a++) for(int y=0;y<N;y++){
    int s=0; for(int i=0;i<N;i++) s += hasL[i][a]*(int)((ROW[y]>>i)&1);
    shellW[a][y]=(1-hasL[y][a])*s;
  }
  int slack[12];
  for(int i=0;i<N;i++){ int s=4-KW[i]-degf(i); slack[i]= s<0?0:s; }
  int credit=0;
  for(int a=0;a<4;a++){
    for(int b=0;b<4;b++) if(b!=a) credit += 3*rootW[a][b];
    for(int y=0;y<N;y++) credit += 3*shellW[a][y];
  }
  int charge=0;
  for(int a=0;a<4;a++){
    for(int b=0;b<4;b++){
      if(b==a) continue;
      int dr=0;
      for(int y=0;y<N;y++) if(shellW[a][y]!=0) dr += hasL[y][b];
      charge += dr*certf(rootW[a][b]);
    }
    for(int y=0;y<N;y++){
      int d=0;
      for(int b=0;b<4;b++) if(b!=a && rootW[a][b]!=0) d += hasL[y][b];
      for(int z=0;z<N;z++) if(z!=y && shellW[a][z]!=0) d += (int)((ROW[y]>>z)&1);
      d += slack[y];
      charge += d*certf(shellW[a][y]);
    }
  }
  return charge + 6*twoT <= credit + 212;
}

/* ---- ChunkP.goGCnt ---- */
static u64 CNT_N, CNT_V;
static void go(int t){
  CNT_N++;
  if(t==NP){ if(!leafOKf()) CNT_V++; return; }
  if(pruneOKf(t)) return;
  int i=PI[t], j=PJ[t];
  go(t+1);
  if(takeGuardf(i,j)){
    ROW[i]|=1u<<j; ROW[j]|=1u<<i;
    go(t+1);
    ROW[i]&=~(1u<<j); ROW[j]&=~(1u<<i);
  }
}

/* ---- ChunkP.expandP / expandPNodes ---- */
static u64 INTERNAL;
static int FR_ROWS[8192][12];
static int FR_T[8192];
static int FR_N;
static void expand(int dd,int t){
  if(dd==0||t==NP){
    for(int i=0;i<N;i++) FR_ROWS[FR_N][i]=(int)ROW[i];
    FR_T[FR_N]=t; FR_N++;
    return;
  }
  if(pruneOKf(t)){ INTERNAL++; return; }
  int i=PI[t], j=PJ[t];
  expand(dd-1,t+1);
  INTERNAL++;
  if(takeGuardf(i,j)){
    ROW[i]|=1u<<j; ROW[j]|=1u<<i;
    expand(dd-1,t+1);
    ROW[i]&=~(1u<<j); ROW[j]&=~(1u<<i);
  }
}

/* ---- MaskGen.genMask ---- */
static u64 MASKS[100000]; static int NMASK;
static int STACKM[16];
static void genMask(int r,int lo,int c0,int c1,int c2,int c3,int depth){
  if(r==0){
    if(c0==0&&c1==0&&c2==0&&c3==0){
      u64 w=0, p=1;
      for(int t=0;t<depth;t++){ w += (u64)STACKM[t]*p; p*=16; }
      MASKS[NMASK++]=w;
    }
    return;
  }
  for(int m=lo;m<16;m++){
    int b0=m%2,b1=m/2%2,b2=m/4%2,b3=m/8%2;
    if(b0<=c0&&b1<=c1&&b2<=c2&&b3<=c3){
      STACKM[depth]=m;
      genMask(r-1,m,c0-b0,c1-b1,c2-b2,c3-b3,depth+1);
    }
  }
}
static void msGen(int n){ NMASK=0; genMask(n,1,3,3,3,3,0); }

int main(int argc,char**argv){
  if(argc<2) return 1;
  if(!strcmp(argv[1],"census")||!strcmp(argv[1],"layer")){
    int lo=3, hi=12;
    if(!strcmp(argv[1],"layer")){ lo=hi=atoi(argv[2]); }
    for(int n=lo;n<=hi;n++){
      msGen(n);
      for(int k=0;k<NMASK;k++){
        setctx(n,MASKS[k]);
        memset(ROW,0,sizeof ROW);
        CNT_N=CNT_V=0; go(0);
        printf("M %d %d %llu %llu %llu\n", n, k, MASKS[k], CNT_N, CNT_V);
      }
    }
    return 0;
  }
  if(!strcmp(argv[1],"expand")){
    int n=atoi(argv[2]); u64 K=strtoull(argv[3],0,10); int d=atoi(argv[4]);
    setctx(n,K); memset(ROW,0,sizeof ROW);
    INTERNAL=0; FR_N=0; expand(d,0);
    printf("INTERNAL %llu\n", INTERNAL);
    for(int s=0;s<FR_N;s++){
      memset(ROW,0,sizeof ROW);
      for(int i=0;i<n;i++) ROW[i]=(unsigned)FR_ROWS[s][i];
      CNT_N=CNT_V=0; go(FR_T[s]);
      printf("S");
      for(int i=0;i<n;i++) printf(" %d", FR_ROWS[s][i]);
      printf(" %llu %llu\n", CNT_N, CNT_V);
    }
    return 0;
  }
  return 1;
}
